ilanlar = [
    "Bulut uzerinde calisan ekip icin SQL ve Python bilgisi aranmaktadir",
    "SQL raporlama ve veri ambari deneyimi; bulut deneyimi tercih sebebidir",
    "Gomulu C gelistirici; python ile test otomasyonu artidir",
    "Bulut mimarisi, kubernetes ve SQL performans ayari",
    "Sahada kurulum destegi; SQL sorgu yazabilen aday",
]

sozluk = {
    "bulut": ["bulut", "kubernetes"],
    "sql": ["sql", "veri ambari"],
    "python": ["python"],
}

sayim = {}
for ad in sozluk:
    sayim[ad] = 0
for ilan in ilanlar:
    metin = ilan.lower()
    for ad, anahtarlar in sozluk.items():
        if any(a in metin for a in anahtarlar):
            sayim[ad] += 1

n = len(ilanlar)
for ad in sorted(sayim, key=lambda k: (-sayim[k], k)):
    oran = round(100.0 * sayim[ad] / n, 1)
    print(ad, sayim[ad], str(oran) + "%")
print("toplam etiket =", sum(sayim.values()))
print("ilan basina etiket =", round(sum(sayim.values()) / n, 2))
